import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game'), scene=new THREE.Scene();
scene.background=new THREE.Color(0x090914); scene.fog=new THREE.FogExp2(0x090914,.018);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,500); camera.position.set(0,11,18);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true}); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.05;
scene.add(new THREE.HemisphereLight(0x8790ba,0x1a0905,1.5)); const moon=new THREE.DirectionalLight(0xadb5ff,2.4); moon.position.set(-12,22,8); moon.castShadow=true; moon.shadow.mapSize.set(2048,2048); moon.shadow.camera.left=-35;moon.shadow.camera.right=35;moon.shadow.camera.top=35;moon.shadow.camera.bottom=-35; scene.add(moon); const fire=new THREE.PointLight(0xff4a18,3.5,28); fire.position.set(0,7,-12);scene.add(fire);

const floor=new THREE.Mesh(new THREE.CircleGeometry(34,48),new THREE.MeshStandardMaterial({color:0x303137,roughness:.85,metalness:.05})); floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
const ringMat=new THREE.MeshStandardMaterial({color:0x11101a,roughness:.7});
for(let r=9;r<29;r+=5){const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.09,8,64),ringMat);ring.rotation.x=Math.PI/2;ring.position.y=.025;scene.add(ring)}
for(let i=0;i<48;i++){const a=i/48*Math.PI*2,r=25+Math.random()*7;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.5+Math.random()*1.2,0),new THREE.MeshStandardMaterial({color:0x292730,roughness:.9}));rock.position.set(Math.cos(a)*r,.2+Math.random()*.4,Math.sin(a)*r);rock.scale.y=.5+Math.random()*1.5;rock.rotation.set(Math.random(),Math.random(),Math.random());rock.castShadow=true;scene.add(rock)}

function cone(a,b,r1,r2,c){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,a,8),new THREE.MeshStandardMaterial({color:c,roughness:.45,metalness:.25}));m.position.copy(b);m.rotation.z=c===0x4d1d15?0:.15;scene.add(m);return m}
// distant ruined pillars
for(let i=0;i<12;i++){const a=i/12*Math.PI*2,r=31;const g=new THREE.Group();const p=new THREE.Mesh(new THREE.CylinderGeometry(.55,.75,6+Math.random()*4,8),new THREE.MeshStandardMaterial({color:0x24212a,roughness:.9}));p.position.y=p.geometry.parameters.height/2;p.castShadow=true;g.add(p);g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);g.rotation.y=-a;scene.add(g)}

function buildWarrior(){const g=new THREE.Group();const armor=0x4a1740,cloth=0x171326,metal=0x9d9ca5;const body=new THREE.Mesh(new THREE.CapsuleGeometry(.65,1.35,5,10),new THREE.MeshStandardMaterial({color:armor,roughness:.38,metalness:.55}));body.position.y=1.7;body.castShadow=true;g.add(body);const chest=new THREE.Mesh(new THREE.BoxGeometry(1.35,.75,.35),new THREE.MeshStandardMaterial({color:metal,roughness:.32,metalness:.8}));chest.position.set(0,2,.42);chest.castShadow=true;g.add(chest);const head=new THREE.Mesh(new THREE.SphereGeometry(.42,16,12),new THREE.MeshStandardMaterial({color:0xb98a73,roughness:.8}));head.position.y=3.15;head.castShadow=true;g.add(head);const helm=new THREE.Mesh(new THREE.ConeGeometry(.48,.75,8),new THREE.MeshStandardMaterial({color:0x4f5059,roughness:.3,metalness:.85}));helm.position.set(0,3.55,0);helm.rotation.y=Math.PI/8;helm.castShadow=true;g.add(helm);for(const s of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.18,.85,4,8),new THREE.MeshStandardMaterial({color:metal,roughness:.35,metalness:.7}));arm.position.set(s*.85,1.75,.05);arm.rotation.z=s*.12;arm.castShadow=true;g.add(arm)}const cape=new THREE.Mesh(new THREE.ConeGeometry(.9,2.1,8,1,true),new THREE.MeshStandardMaterial({color:cloth,roughness:.8,side:THREE.DoubleSide}));cape.position.set(0,1.75,-.55);cape.rotation.x=.12;g.add(cape);const sword=new THREE.Group();const blade=new THREE.Mesh(new THREE.BoxGeometry(.09,1.55,.025),new THREE.MeshStandardMaterial({color:0xdedce6,roughness:.18,metalness:1,emissive:0x241e34}));blade.position.y=.75;blade.castShadow=true;sword.add(blade);const guard=new THREE.Mesh(new THREE.BoxGeometry(.55,.08,.08),new THREE.MeshStandardMaterial({color:0xd0a44d,metalness:.9,roughness:.25}));sword.add(guard);sword.position.set(.95,1.35,.2);sword.rotation.z=-.65;sword.rotation.x=-.15;g.add(sword);g.userData.sword=sword;g.position.set(0,0,8);scene.add(g);return g}
const warrior=buildWarrior();

function buildDragon(){const g=new THREE.Group();const red=0x6a1718,dark=0x241117,wing=0x35151b,bone=0xa58361;const body=new THREE.Mesh(new THREE.SphereGeometry(2.2,24,16),new THREE.MeshStandardMaterial({color:red,roughness:.55,metalness:.15}));body.scale.set(1.15,.95,1.5);body.position.y=3.4;body.castShadow=true;g.add(body);const chest=new THREE.Mesh(new THREE.SphereGeometry(1.75,20,12),new THREE.MeshStandardMaterial({color:0x8c2420,roughness:.5}));chest.scale.set(.9,.75,.5);chest.position.set(0,2.9,1.7);g.add(chest);
for(const s of [-1,1]){const wingG=new THREE.Group();const membrane=new THREE.Mesh(new THREE.ConeGeometry(3.7,7,3),new THREE.MeshStandardMaterial({color:wing,roughness:.7,side:THREE.DoubleSide}));membrane.scale.set(.15,1,.7);membrane.rotation.z=s*.95;membrane.rotation.y=s*.25;membrane.position.set(s*3.2,4.2,-.2);membrane.castShadow=true;wingG.add(membrane);const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.38,3,5,8),new THREE.MeshStandardMaterial({color:red,roughness:.5}));arm.position.set(s*2.2,3,.8);arm.rotation.z=s*.7;arm.castShadow=true;wingG.add(arm);g.add(wingG);g.userData['w'+(s<0?'l':'r')]=wingG}
const neck=new THREE.Mesh(new THREE.CapsuleGeometry(.75,1.7,6,10),new THREE.MeshStandardMaterial({color:red,roughness:.5}));neck.position.set(0,4.5,2.1);neck.rotation.x=-.75;neck.castShadow=true;g.add(neck);const head=new THREE.Mesh(new THREE.SphereGeometry(1.15,20,12),new THREE.MeshStandardMaterial({color:red,roughness:.45}));head.scale.set(1.1,.75,1.35);head.position.set(0,5.7,3.1);head.castShadow=true;g.add(head);const snout=new THREE.Mesh(new THREE.ConeGeometry(.72,1.3,8),new THREE.MeshStandardMaterial({color:0x391215,roughness:.6}));snout.position.set(0,5.45,4.15);snout.rotation.x=Math.PI/2;g.add(snout);for(const s of [-1,1]){const horn=new THREE.Mesh(new THREE.ConeGeometry(.18,.95,7),new THREE.MeshStandardMaterial({color:bone,roughness:.5}));horn.position.set(s*.75,6.45,2.7);horn.rotation.z=s*.55;horn.rotation.x=-.2;g.add(horn);const eye=new THREE.Mesh(new THREE.SphereGeometry(.12,8,8),new THREE.MeshStandardMaterial({color:0xff3b18,emissive:0xff1600,emissiveIntensity:5}));eye.position.set(s*.42,5.85,4.05);g.add(eye)}const tail=new THREE.Mesh(new THREE.CapsuleGeometry(.45,4.8,6,10),new THREE.MeshStandardMaterial({color:dark,roughness:.6}));tail.position.set(0,2,-3.7);tail.rotation.x=.65;tail.castShadow=true;g.add(tail);g.position.set(0,0,-10);scene.add(g);return g}
const dragon=buildDragon();

// fire embers
const embers=[];for(let i=0;i<70;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.025+Math.random*.04,5,5),new THREE.MeshBasicMaterial({color:i%3?0xff791b:0xffcf62}));m.position.set((Math.random-.5)*30,Math.random()*12,(Math.random-.5)*30);scene.add(m);embers.push(m)}

let keys={},vx=0,vz=0,health=100,bossHealth=100,last=performance.now(),attacking=false,dashing=false,gameOver=false,coins=240,attackTime=0;
addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='Space'||e.code==='KeyJ')attack();if(e.code==='ShiftLeft'||e.code==='KeyK')dash()});addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('pointerdown',e=>{if(e.button===0)attack();else dash()});
function attack(){if(attacking||dashing||gameOver)return;attacking=true;attackTime=0;const sword=warrior.userData.sword;setTimeout(()=>{if(!gameOver){const d=warrior.position.distanceTo(dragon.position);if(d<8.5){bossHealth=Math.max(0,bossHealth-(d<5?12:7));update();spawnDamage(d<5?'12':'7');if(bossHealth<=0)end(true)}}},180);setTimeout(()=>attacking=false,520)}
function dash(){if(dashing||gameOver)return;dashing=true;const ahead=new THREE.Vector3();camera.getWorldDirection(ahead);ahead.y=0;ahead.normalize();vx=ahead.x*18;vz=ahead.z*18;setTimeout(()=>dashing=false,230)}
function spawnDamage(text){const el=document.createElement('div');el.className='damage';el.textContent='-'+text;el.style.left=(innerWidth*.5+(Math.random-.5)*120)+'px';el.style.top=(innerHeight*.4)+'px';document.body.appendChild(el);requestAnimationAnimationFrame(()=>{el.style.top=(innerHeight*.32)+'px';el.style.opacity='0'});setTimeout(()=>el.remove(),700)}
function update(){document.querySelector('#health').style.width=health+'%';document.querySelector('#boss').style.width=bossHealth+'%';document.querySelector('#coins').textContent=coins}
function end(win){gameOver=true;const p=document.querySelector('#panel');document.querySelector('#title').textContent=win?'VICTORY':'DEFEATED';document.querySelector('#subtitle').textContent=win?'The ancient darkness retreats.':'The Flame Drake reigns over the arena.';p.classList.remove('hidden')}
document.querySelector('#restart').onclick=()=>location.reload();

let toastTimer=setTimeout(()=>document.querySelector('#toast').classList.add('show'),400);setTimeout(()=>document.querySelector('#toast').classList.remove('show'),2600);

function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.033);last=now;
// movement
let ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),iz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);if(!dashing){vx=ix*6;vz=iz*6}else vx*=.97,vz*=.97;if(vx||vz){warrior.position.x+=vx*dt;warrior.position.z+=vz*dt;const angle=Math.atan2(vx,vz);warrior.rotation.y=angle}warrior.position.x=THREE.MathUtils.clamp(warrior.position.x,-23,23);warrior.position.z=THREE.MathUtils.clamp(warrior.position.z,-20,18);
// attack pose
if(attacking){attackTime+=dt;warrior.userData.sword.rotation.z=-.65+Math.sin(attackTime*18)*1.6}else warrior.userData.sword.rotation.z=-.65;
// dragon motion
const dist=warrior.position.distanceTo(dragon.position);if(!gameOver&&bossHealth>0){dragon.position.y=Math.sin(now*.0015)*.25;dragon.rotation.y=Math.sin(now*.0004)*.12;guth=dragon.position.clone();const dir=new THREE.Vector3().subVectors(warrior.position,dragon.position);dir.y=0;if(dist>5&&dist<25){dir.normalize();dragon.position.addScaledVector(dir,dt*(bossHealth<35?2:1.15));}dragon.lookAt(warrior.position.x,3,warrior.position.z);dragon.userData.wl.rotation.z=.35+Math.sin(now*.001)*.12;dragon.userData.wr.rotation.z=-.35-Math.sin(now*.001)*.12;if(dist<7&&Math.random()<dt*.55){health=Math.max(0,health-7);update();if(health<=0)end(false)}}
for(let i=0;i<embers.length;i++){const e=embers[i];e.position.y+=dt*(.15+i*.001);if(e.position.y>12)e.position.y=0}
// camera follow
theCam=new THREE.Vector3(warrior.position.x,9,warrior.position.z+15);camera.position.lerp(theCam,.06);camera.lookAt(warrior.position.x,2.2,warrior.position.z-2);
renderer.render(scene,camera)}requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
EOF
